#Relational Operators: used to compare values. <, >, <=, >=, ==, !=
n1,n2=10,5
print("n1:", n1)
print("n2:", n2)
print("n1 > n2:", n1 > n2)
print("n1 < n2:", n1 < n2)
print("n1 >= n2:", n1 >= n2)
print("n1 <= n2:", n1 <= n2)
print("n1 == n2:", n1 == n2)
print("n1 != n2:", n1 != n2)

n=n1==n2+5# 1st compleate the arithmetic operation then it will compare the value
print(n)